import { Router } from "express";

export interface Item {
  id: number;
  name: string;
  createdAt: number;
}

// Seeded in id order. Treated as the canonical store for the lifetime of the process.
const ITEMS: Item[] = Array.from({ length: 47 }, (_, i) => ({
  id: i,
  name: `Item ${String(i).padStart(2, "0")}`,
  createdAt: Date.now() - i * 1000,
}));

const router = Router();

router.get("/items", (req, res) => {
  const page = parseInt(String(req.query.page ?? "1"), 10);
  const pageSize = parseInt(String(req.query.pageSize ?? "10"), 10);
  const q = String(req.query.q ?? "").trim().toLowerCase();
  const sort = String(req.query.sort ?? "");

  let result = ITEMS;
  if (q) {
    result = result.filter((it) => it.name.toLowerCase().includes(q));
  }
  if (sort === "name") {
    result = result.sort((a, b) => a.name.localeCompare(b.name));
  }

  const start = (page - 1) * pageSize;
  const slice = result.slice(start, start + pageSize);

  res.json({ items: slice, page, pageSize, totalCount: result.length });
});

export default router;

