import { useEffect, useState } from "react";

export interface Item {
  id: number;
  name: string;
  createdAt: number;
}

interface ItemsResponse {
  items: Item[];
  page: number;
  pageSize: number;
  total: number;
}

export function useItems(page: number, pageSize: number, query: string) {
  const [items, setItems] = useState<Item[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    setLoading(true);
    fetch(`/items?page=${page}&pageSize=${pageSize}&q=${encodeURIComponent(query)}`)
      .then((r) => r.json())
      .then((data: ItemsResponse) => {
        setItems(data.items);
        setTotal(data.total);
      })
      .finally(() => setLoading(false));
  }, [page, pageSize, query]);

  return { items, total, loading };
}

